describe('Gallery Lightbox', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/gallery');
    cy.viewport(1280, 720);
  });

  it('should open lightbox when clicking an image in the gallery', () => {
    cy.get('[data-testid="gallery-image"]').first().click();

    cy.get('[data-testid="lightbox-modal"]').should('be.visible');
    cy.get('[data-testid="lightbox-image"]').should('be.visible');
    cy.get('[data-testid="lightbox-image"]').should('have.attr', 'src');
  });

  it('should close lightbox when clicking the close button', () => {
    cy.get('[data-testid="gallery-image"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    cy.get('[data-testid="lightbox-close-btn"]').click();
    cy.get('[data-testid="lightbox-modal"]').should('not.be.visible');
  });

  it('should close lightbox when pressing the Escape key', () => {
    cy.get('[data-testid="gallery-image"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    cy.get('body').type('{esc}');
    cy.get('[data-testid="lightbox-modal"]').should('not.be.visible');
  });

  it('should navigate to next image when clicking next button', () => {
    cy.get('[data-testid="gallery-image"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    cy.get('[data-testid="lightbox-image"]').then(($img) => {
      const firstSrc = $img.attr('src');

      cy.get('[data-testid="lightbox-next-btn"]').click();
      cy.get('[data-testid="lightbox-image"]').should('have.attr', 'src').and('not.equal', firstSrc);
    });
  });

  it('should navigate to previous image when clicking previous button', () => {
    cy.get('[data-testid="gallery-image"]').eq(1).click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    cy.get('[data-testid="lightbox-image"]').then(($img) => {
      const currentSrc = $img.attr('src');

      cy.get('[data-testid="lightbox-prev-btn"]').click();
      cy.get('[data-testid="lightbox-image"]').should('have.attr', 'src').and('not.equal', currentSrc);
    });
  });

  it('should close lightbox when clicking outside the image', () => {
    cy.get('[data-testid="gallery-image"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    cy.get('[data-testid="lightbox-backdrop"]').click({ force: true });
    cy.get('[data-testid="lightbox-modal"]').should('not.be.visible');
  });

  it('should handle edge case when gallery has only one image', () => {
    cy.get('[data-testid="gallery-image"]').then(($images) => {
      if ($images.length === 1) {
        cy.get('[data-testid="gallery-image"]').click();
        cy.get('[data-testid="lightbox-modal"]').should('be.visible');

        cy.get('[data-testid="lightbox-next-btn"]').should('be.disabled');
        cy.get('[data-testid="lightbox-prev-btn"]').should('be.disabled');
      }
    });
  });
});
